window.AUTH=window.AUTH||{};window.AUTH["11-192"]={"d":"11-192","id":"2012/11-192","n":"United States v. Bormes","src":["osg"],"briefs":[{"k":"reply","label":"Reply brief for the United States","date":"","url":"https://www.justice.gov/osg/media/224736/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/united-states-v-bormes-reply-merits","n":72},{"k":"petitioner","label":"Brief for the United States","date":"","url":"https://www.justice.gov/osg/media/196876/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/united-states-v-bormes-briefs-merits","n":113}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep568/usrep568006/usrep568006.pdf","tr":true,"items":[{"t":"case","label":"Army & Air Force Exch. Serv. v. Sheehan","cite":"456 U.S. 728","y":1982,"id":"1981/80-1437","sc":1,"sum":"The Tucker Act did not confer jurisdiction over respondent's claim for money damages.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3, 4","1":"27"}},{"t":"case","label":"Babbitt v. Youpee","cite":"519 U.S. 234","y":1997,"id":"1996/95-1595","sc":1,"sum":"Authored by Justice Ruth Bader Ginsburg, The Court ruled that the amended Section 207 of the Indian Land Consolidation Act does not cure the constitutional deficiency The Court identified in the original version of Section 207, which amounted to a taking of private property without just compensation, in violation of the Fifth Amendment.","sumSrc":"Oyez","by":{"0":"7"}},{"t":"case","label":"Basso v. United States","cite":"239 U.S. 602","y":1916,"id":"scdb/1915-223","sc":1,"sum":"The rule that the Court of Claims has not jurisdiction of actions founded on tort is based on a policy imposed by necessity that governments are not liable for unauthorized wrongs inflicted on the citizens by their officers, even though occurring while engaged in discharge of official duties. Schillinger v. United States, 155 U. S. 163.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"9","1":"30"}},{"t":"case","label":"Brown v. General Servs. Admin.","cite":"425 U.S. 820","y":1976,"id":"1975/74-768","sc":1,"sum":"Section 717 provides the exBROWN v. GSA","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3, 4","1":"21, 24, 29, 38"}},{"t":"case","label":"City of Monterey v. Del Monte Dunes at Monterey, Ltd.","cite":"526 U.S. 687","y":1999,"id":"1998/97-1235","sc":1,"sum":"The Court held, in an opinion authored by Justice Anthony M. Kennedy, that property owners who file a Section 1983 civil rights suit seeking compensation for an alleged taking of their property can have a jury trial in some circumstances. \"[T]he disputed questions were whether the government had denied a constitutional right outside the bounds of its authority, and, if so, the extent of any resulting damages.\" Justice Kennedy then added: \"These were questions for the jury.\".","sumSrc":"Oyez","by":{"0":"12"}},{"t":"case","label":"Curtis v. Loether","cite":"415 U.S. 189","y":1974,"id":"1973/72-1035","sc":1,"sum":"The Seventh Amendment of the Constitution entitles either party to demand a jury trial in an action for damages in the federal courts under § 812 of the Civil Rights Act of 1968, which authorizes privateplaintiffs to bring civil actions to redress violations of the Act's fair housing provisions. Pp. 191-198. 467 F. 2d 1110, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12"}},{"t":"case","label":"Department of the Army v. Blue Fox, Inc.","cite":"525 U.S. 255","y":1999,"id":"1998/97-1642","sc":1,"sum":"Announced by Chief Justice William H. Rehnquist, the Court ruled that \"unless waived by Congress, sovereign immunity bars subcontractors and other creditors from enforcing liens on government property or funds to recoup their losses.\" The APA prohibits people and companies with grievances from suing the government for monetary damages.","sumSrc":"Oyez","by":{"0":"8"}},{"t":"case","label":"Dooley v. United States","cite":"182 U.S. 222","y":1901,"id":"scdb/1900-060","sc":1,"ar":2,"sum":"The Court of Claims, and the Circuit Courts, acting as such, have jurisdiction of actions for the recovery of duties illegally exacted uponmerchan- disc, alleged not to have been imported from a foreign country.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"9"}},{"t":"case","label":"Eastern Enters. v. Apfel","cite":"524 U.S. 498","y":1998,"id":"1997/97-42","sc":1,"sum":"Currently unknown.","sumSrc":"Oyez","by":{"0":"7"}},{"t":"case","label":"Employees of the Dep’t of Pub. Health & Welfare v. Department of Pub. Health & Welfare","cite":"411 U.S. 279","y":1973,"id":"1972/71-1021","sc":1,"sum":"Although amendments to the FLSA in 1966 extended statutory coverage to state employees, the legislative history discloses no congressional purpose to deprive a State of its constitutional immunity to suit in a federal forum by employees of its nonprofit institutions, particularly since Congress made no change in § 16 (b); which makes no reference to suits by employees against the State. Parden v. Terminal R. Co., …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17","1":"45"}},{"t":"case","label":"FAA v. Cooper","cite":"132 S. Ct. 1441","y":2012,"id":"2011/10-1024","sc":1,"sum":"The Court held that the Privacy Act of 1974 does not cover mental and emotional distress under \"actual damages.\"","sumSrc":"Oyez","by":{"0":"8, 13"}},{"t":"case","label":"Farmers Reservoir & Irrigation Co. v. McComb","cite":"337 U.S. 755","y":1949,"id":"scdb/1948-108","sc":1,"sum":"The sole activity of a mutual irrigation company owned entirely by farmers is the collection, storage and distribution of water for irrigation purposes, wholly within Colorado. The water is sup-plied by the company to farmers at headgates on the company's canals, whence it is taken into the farmers' own laterals and used by them in the production of agricultural products to be shipped in interstate commerce. The …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17","1":"43"}},{"t":"case","label":"General Dynamics Land Sys., Inc. v. Cline","cite":"540 U.S. 581","y":2004,"id":"2003/02-1080","sc":1,"sum":"Justice David H. Souter delivered the Court's 6-3 opinion that the Age Discrimination in Employment Act's \"text, structure, purpose, history, and relationship to other federal statutes show that the statute does not mean to stop an employer from favoring an older employee over a younger one.\" The Court cited a long-held understanding of the \"ADEA as a remedy for unfair preference based on relative youth, leaving complaints of the relatively young outside the statutory concern.\" The Court also noted the findings section of the act included no evidence of younger workers being discriminated against in favor of older workers.","sumSrc":"Oyez","by":{"0":"16, 17","1":"41"}},{"t":"case","label":"Hinck v. United States","cite":"550 U.S. 501","y":2007,"id":"2006/06-376","sc":1,"op":3,"ar":3,"sum":"The Court reasoned that its ruling was consistent with the principle that when Congress enacts a detailed, specific judicial remedy (such as 6404(e)(1)) where there was no remedy before, the new remedy will be regarded as exclusive.","sumSrc":"Oyez","by":{"0":"3","1":"passim"}},{"t":"case","label":"Hodel v. Irving","cite":"481 U.S. 704","y":1987,"id":"1986/85-637","sc":1,"sum":"The Court held that the section of the Indian Land Consolidation Act which transferred ownership of fractional land interests to the respective tribe constituted an unconstitutional seizure of property without just compensation. The Court also held that the plaintiffs had standing to challenge the provision.","sumSrc":"Oyez","by":{"0":"7"}},{"t":"case","label":"Hollister v. Benedict & Burnham Mfg. Co.","cite":"113 U.S. 59","y":1885,"id":"scdb/1884-090","sc":1,"sum":"— Decided January 5, 1885.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"10"}},{"t":"case","label":"Hurley v. Kincaid","cite":"285 U.S. 95","y":1932,"id":"scdb/1931-086","sc":1,"sum":"1. An owner of land lying within the proposed channel of the Bocuf Floodway, part of the plan authorized by the Mississippi River Flood Control Act, brought suit to enjoin the carrying out of the work in the floodway and specifically to enjoin the receiving of bids for the construction of the guide-levees therefor, claiming that if the work should be commenced without proceedings first having been instituted to …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"10"}},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"sum":"The Court held that habeas jurisdiction was not repealed by AEDPA and IIRIRA.","sumSrc":"Oyez","by":{"0":"5","1":"54"}},{"t":"case","label":"Jacobs v. United States","cite":"290 U.S. 13","y":1933,"id":"scdb/1933-035","sc":1,"ar":5,"sum":"1. The obligation of the United States to pay just compensation for private property taken under its power of eminent domain rests upon the Fifth Amendment, independent of statute or express promise.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"9, 10"}},{"t":"case","label":"Koons Buick Pontiac GMC, Inc. v. Nigh","cite":"543 U.S. 50","y":2004,"id":"2004/03-377","sc":1,"sum":"In an 8-1 judgment delivered by Justice Ruth Bader Ginsburg, the Court held that a 1995 TILA amendment did not change the original limit on violations involving personal-property loans. Congress intended the amendment to raise the minimum and maximum recoveries for closed-end loans secured by real property. Congress had not sought to remove the $1,000 cap on loans secured by personal property.","sumSrc":"Oyez","by":{"0":"20","1":"50"}},{"t":"case","label":"Labine v. Vincent","cite":"401 U.S. 532","y":1971,"id":"1970/5257","sc":1,"sum":"The Louisiana statutory intestate succession schem6 is within the State's power to establish rule§ for the protection and strengthening of family life and for the disposition of property, and in view of various statutory alternatives, none of. which was chosen by Vincent, did not (unlike the situation in Levy) constitute an insurmountable barrier to illegitimate children. Pp. 535-540: 255 La. 480, 231 So. 2d 395, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13"}},{"t":"case","label":"Lane v. Peña","cite":"518 U.S. 187","y":1996,"id":"1995/95-365","sc":1,"ar":1,"sum":"Although the related provisions of the 1973 Rehabilitation Act and the 1991 Civil Rights Act might in combination be read as waiving the federal government's sovereign immunity, absent an unambiguous waiver of sovereign immunity, the court cannot permit damages to be awarded.","sumSrc":"Oyez","by":{"0":"1, 3, 4","1":"9, 16, 28, 29"}},{"t":"case","label":"Lawson v. Suwannee Fruit & S.S. Co.","cite":"336 U.S. 198","y":1949,"id":"scdb/1948-038","sc":1,"sum":"Under § 8 (f) (1) of the Act, the employer was liable only for permanent partial disability (loss of the left eye), and the remainder of the compensation due for permanent total disability was payable out of the special fund established by § 44 of the Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17, 18"}},{"t":"case","label":"Nichols v. United States","cite":"74 U.S. 122","y":1869,"id":"scdb/1868-032","sc":1,"op":1,"ar":1,"sum":"An act of Congress of February 26, 1845, construing, a former act relative to duties paid under protest, says:","sumSrc":"Headnote (U.S. Reports)","by":{"0":"3, 4","1":"10, 21, 25"}},{"t":"case","label":"Northwest Austin Mun. Util. Dist. No. 1 v. Holder","cite":"557 U.S. 193","y":2009,"id":"2008/08-322","sc":1,"sum":"The Court held that the Voting Rights Act (VRA) permits all political subdivisions to seek bailout from the preclearance requirements of the VRA.","sumSrc":"Oyez","by":{"0":"17, 18"}},{"t":"case","label":"OPM v. Richmond","cite":"496 U.S. 414","y":1990,"id":"1989/88-1943","sc":1,"sum":"The Court held that the Appropriations Clause of the Constitution explicitly states that no money can be paid from the Treasury unless specifically authorized by a statute. Since there is a statute that denies Richmond his benefits, and there is not one that provides an exception, the Court held that Richmond’s receipt of incorrect information cannot affect the non-payment of his benefits.","sumSrc":"Oyez","by":{"0":"5","1":"54"}},{"t":"case","label":"Philko Aviation, Inc. v. Shacket","cite":"462 U.S. 406","y":1983,"id":"1982/82-342","sc":1,"sum":"State laws, such as the Illinois law, allowing undocumented or unrecorded transfers of interests in aircraft to affect innocent third parties are pre-empted by the federal Act. Although if § 508(c) were interpreted literally in accordance with the federal Act's definition of \"conveyance\"--\"a bill of sale, contract of conditional sale, mortgage, assignment of mortgage, or other instrument affecting title to, or …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Preseault v. ICC","cite":"494 U.S. 1","y":1990,"id":"1989/88-1076","sc":1,"sum":"Because pre-existing federal law failed to deal adequately with the national problem of shrinking rail trackage, Congress enacted the National Trails System Act Amendments of 1983 (Amendments) to the National Trails System Act (Trails Act), which authorize the Interstate Commerce Commission (ICC or Commission) to preserve for possible future railroad use rights-of-way not currently in service and to allow interim …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"7"}},{"t":"case","label":"Quern v. Jordan","cite":"440 U.S. 332","y":1979,"id":"1978/77-841","sc":1,"sum":"In Edelman v. Jordan, 415 U. S. 651, it was held that retroactive welfare benefits awarded by a Federal District Court to the plaintiff class, by reason of wrongful denial of benefits by Illinois officials prior to the entry of the court's order determining the wrongfulness of their actions, violated the Eleventh Amendment, and that in an action under 42 U. S. C. § 1983 \"a federal court's remedial power, consistent …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20, 21"}},{"t":"case","label":"Roberts v. Sea-Land Servs., Inc.","cite":"132 S. Ct. 1350","y":2012,"id":"2011/10-1399","sc":1,"sum":"The Court held that the Longshore Act sets the period when an injured worker is awarded disability compensation as the fiscal year when the worker first becomes entitled to compensation.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Ruckelshaus v. Monsanto Co.","cite":"467 U.S. 986","y":1984,"id":"1983/83-196","sc":1,"ar":1,"sum":"The Federal Insecticide, Fungicide, and Rodenticide Act (FIFRA) authorizes the Environmental Protection Agency (EPA) to use data submitted by an applicant for registration of a covered product (hereinafter pesticide) in evaluating the application of a subsequent applicant, and to disclose publicly some of the submitted data. Under the dataconsideration provisions of § 3, as amended in 1978, applicants now are …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"7, 9"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"Safeco Ins. Co. of Am. v. Burr","cite":"551 U.S. 47","y":2007,"id":"2006/06-84","sc":1,"op":1,"ar":1,"sum":"The Court ruled that insurance companies can be liable for willful violations of the Fair Credit Reporting Act if they show \"reckless disregard\" for the law. The justices held that the meaning of the term \"willful\" is contextually determined.","sumSrc":"Oyez","by":{"0":"12","1":"23, 31"}},{"t":"case","label":"Schillinger v. United States","cite":"155 U.S. 163","y":1894,"id":"scdb/1894-019","sc":1,"sum":"The United States cannot be sued in their courts without their consent.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"8, 9, 11","1":"12, 30, 32"}},{"t":"case","label":"Seminole Tribe v. Florida","cite":"517 U.S. 44","y":1996,"id":"1995/94-12","sc":1,"sum":"In a 5-to-4 decision, The Court held that Congress did intend to abrogate states' sovereign immunity under the IGRA but that the Indian Commerce Clause (and by implication the Commerce Clause) did not give Congress that power. Under the Eleventh Amendment, all states are regarded as sovereign entities.","sumSrc":"Oyez","by":{"0":"18","1":"14, 47"}},{"t":"case","label":"United States v. A.S. Kreider Co.","cite":"313 U.S. 443","y":1941,"id":"scdb/1940-133","sc":1,"sum":"1. Section 24 (20) of the Judicial Code, which gives the District Courts jurisdiction concurrent with the Court of Claims over certain suits against the United States, provides that no suit shall be allowed thereunder unless the same shall have been brought within six years after the right accrued for which the claim is made. Held, that the six-years period is an outside limit consistent with the five-years limit on …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16","1":"38, 39"}},{"t":"case","label":"United States v. Causby","cite":"328 U.S. 256","y":1946,"id":"1940-1955/328us256","sc":1,"sum":"The Court concluded that the ancient common law doctrine \"has no place in the modern world.\" Justice Douglas noted that, were the Court to accept the doctrine as valid, \"every transcontinental flight would subject the operator to countless trespass suits.","sumSrc":"Oyez","by":{"0":"7, 9, 10"}},{"t":"case","label":"United States v. Cleveland Indians Baseball Co.","cite":"532 U.S. 200","y":2001,"id":"2000/00-203","sc":1,"sum":"The Court held that back wages are subject to FICA and FUTA taxes by reference to the year the wages are in fact paid. \"Although the regulations, like the statute, do not specifically address backpay, the Internal Revenue Service has consistently interpreted them to require taxation of back wages according to the year the wages are actually paid, regardless of when those wages were earned or should have been paid,\" wrote Justice Ginsburg for the Court.","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"United States v. Clintwood Elkhorn Mining Co.","cite":"553 U.S. 1","y":2008,"id":"2007/07-308","sc":1,"sum":"Jr., the Court refused to pay Clintwood refunds for the unconstitutionally levied taxes. The Court stated that the remedy for taxes imposed in violation of the Export Clause is the same as for any other unlawful tax: filing a timely administrative refund claim.","sumSrc":"Oyez","by":{"0":"15","1":"39"}},{"t":"case","label":"United States v. Cooper Corp.","cite":"312 U.S. 600","y":1941,"id":"scdb/1940-054","sc":1,"sum":"1. While the United States is a juristic person in the sense that it can sue upon its contracts or in vindication of its property rights, the term \"person\" does not include the sovereign, in common usage, nor, ordinarily, when employed in statutes.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18"}},{"t":"case","label":"United States v. Erika, Inc.","cite":"456 U.S. 201","y":1982,"id":"1981/80-1594","sc":1,"op":1,"ar":2,"sum":"The Court of Claims has no jurisdiction to review determinations by private insurance carriers of the amount of benefits payable under Part B of the Medicare program.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3, 4","1":"22, 25, 26"}},{"t":"case","label":"United States v. Fausto","cite":"484 U.S. 439","y":1988,"id":"1987/86-595","sc":1,"op":1,"sum":"The CSRA, which affords to nonpreference eligibles in the excepted service no administrative or judicial review of adverse personnel action of the type involved here, precludes judicial review for those employees under the Tucker Act based on the Back Pay Act. The CSRA was designed to replace the haphazard arrangements that had built up over almost a century with one integrated system for administrative and judicial …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3","1":"22, 24, 25, 36"}},{"t":"case","label":"United States v. Mitchell","cite":"463 U.S. 206","y":1983,"id":"1982/81-1748","sc":1,"op":2,"sum":"The United States is accountable in money damages for alleged breaches of trust in connection with its management of forest resources on allotted lands of the Quinault Reservation.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5, 6, 10, 21","1":"passim"}},{"t":"case","label":"United States v. Navajo Nation","cite":"556 U.S. 287","y":2009,"id":"2008/07-1410","sc":1,"op":1,"sum":"The Court held that its decision in Navajo I did not terminate the defendant's claim, however, the defendant did not provide sufficient sources of law and therefore the suit should be dismissed.","sumSrc":"Oyez","by":{"0":"5, 6","1":"26, 37"}},{"t":"case","label":"United States v. Nederlandsch-Amerikaansche Stoomvart Maatschappij","cite":"254 U.S. 148","y":1920,"id":"scdb/1920-015","sc":1,"sum":"A foreign steamship company alleged that, under duress practiced by the immigration authorities, it paid bills rendered by them under color of the Immigration Act, for maintenance and medical care. furnished by the United States to certain immigrants who, after landing from the company’s ships, were temporarily detained before being admitted to the country, and it claimed reimbursement under the Tucker Act, upon the …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"9"}},{"t":"case","label":"United States v. Public Utils. Comm’n","cite":"345 U.S. 295","y":1953,"id":"scdb/1952-073","sc":1,"sum":"The rates for such sales of power for resale are subject to regulation by the Federal Power Commission under Part II of the Federal Power Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17","1":"42"}},{"t":"case","label":"United States v. Sherwood","cite":"312 U.S. 584","y":1941,"id":"scdb/1940-058","sc":1,"sum":"A New York court, acting under authority of § 795 of the New York Civil Practice Act, made an order authorizing a judgment creditor to sue under the Tucker Act, to recover damages from the United States for breach of its contract with the. judgment debtor, the order directing that out of the recovery the judgment creditor should be entitled to a sum sufficient to satisfy his judgment with interest, costs, etc. The …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14","1":"6, 35"}},{"t":"case","label":"United States v. Testan","cite":"424 U.S. 392","y":1976,"id":"1975/74-753","sc":1,"sum":"Respondent Government trial attorneys with civil service grade GS-13 classifications requested their employing agency to reclassify their positions to grade GS-14, contending that their duties and responsibilities met the requirements for the higher grade and were identical to those of other trial attorneys classified as GS-14 in another agency, and that under the principle of \"equal pay for substantially equal …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3, 4","1":"27"}},{"t":"case","label":"United States v. Tohono O’Odham Nation","cite":"131 S. Ct. 1723","y":2011,"id":"2010/09-846","sc":1,"sum":"The Court held that the Court of Federal Claims lacked jurisdiction to hear a suit against the federal government about a claim already being litigated against the government in another court, even when the lawsuits seek different relief based on the same set of facts.","sumSrc":"Oyez","by":{"0":"9","1":"30"}},{"t":"case","label":"United States v. White Mountain Apache Tribe","cite":"537 U.S. 465","y":2003,"id":"2002/01-1067","sc":1,"op":4,"ar":4,"sum":"The Court held that Public Law 86-392 gives rise to Indian Tucker Act jurisdiction in the Court of Federal Claims over the Tribe's suit.","sumSrc":"Oyez","by":{"0":"10","1":"7, 8, 26, 27, 40"}},{"t":"case","label":"United States Dep’t of Energy v. Ohio","cite":"503 U.S. 607","y":1992,"id":"1991/90-1341","sc":1,"sum":"Congress has not waived the National Government's sovereign immunity from liability for civil fines imposed by a State for past violations of the CWA or RCRA.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4","1":"29"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"10"}},{"t":"law","label":"Equal Credit Opportunity Act, Pub. L. No. 90-321","url":"https://www.govinfo.gov/link/statute/88/1521","by":{"0":"19"}},{"t":"law","label":"Pub. L. No. 94-239","url":"https://www.govinfo.gov/link/statute/90/253","by":{"0":"19"}},{"t":"usc","label":"15 U.S.C. § 1681","url":"https://www.law.cornell.edu/uscode/text/15/1681","stext":{"head":"§1681. Congressional findings and statement of purpose","paras":[[0,"(a) Accuracy and fairness of credit reporting"],[0,"The Congress makes the following findings:"],[0,"(1) The banking system is dependent upon fair and accurate credit reporting. Inaccurate credit reports directly impair the efficiency of the banking system, and unfair credit reporting methods undermine the public confidence which is essential to the continued functioning of the banking system."],[0,"(2) An elaborate mechanism has been developed for investigating and evaluating the credit worthiness, credit standing, credit capacity, character, and general reputation of consumers."],[0,"(3) Consumer reporting agencies have assumed a vital role in assembling and evaluating consumer credit and other information on consumers."],[0,"(4) There is a need to insure that consumer reporting agencies exercise their grave responsibilities with fairness, impartiality, and a respect for the consumer's right to privacy."],[0,"(b) Reasonable procedures"],[0,"It is the purpose of this subchapter to require that consumer reporting agencies adopt reasonable procedures for meeting the needs of commerce for consumer credit, personnel, insurance, and other information in a manner which is fair and equitable to the consumer, with regard to the confidentiality, accuracy, relevancy, and proper utilization of such information in accordance with the requirements of this subchapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1681. Congressional findings and statement of purpose","tname":"Commerce and Trade","by":{"0":"17","1":"2, 3"}},{"t":"usc","label":"15 U.S.C. § 1681a","url":"https://www.law.cornell.edu/uscode/text/15/1681a","subs":["(b)","(d)(1)","(f)","(k)(1)(B)(ii)"],"stext":{"head":"§1681a. Definitions; rules of construction","paras":[[0,"(a) Definitions and rules of construction set forth in this section are applicable for the purposes of this subchapter."],[0,"(b) The term \"person\" means any individual, partnership, corporation, trust, estate, cooperative, association, government or governmental subdivision or agency, or other entity."],[0,"(c) The term \"consumer\" means an individual."],[0,"(d) Consumer Report.—"],[1,"(1) In general.—The term \"consumer report\" means any written, oral, or other communication of any information by a consumer reporting agency bearing on a consumer's credit worthiness, credit standing, credit capacity, character, general reputation, personal characteristics, or mode of living which is used or expected to be used or collected in whole or in part for the purpose of serving as a factor in establishing the consumer's eligibility for—"],[2,"(A) credit or insurance to be used primarily for personal, family, or household purposes;"],[2,"(B) employment purposes; or"],[2,"(C) any other purpose authorized under section 1681b of this title."],[1,"(2) Exclusions.—Except as provided in paragraph (3), the term \"consumer report\" does not include—"],[2,"(A) subject to section 1681s–3 of this title, any—"],[3,"(i) report containing information solely as to transactions or experiences between the consumer and the person making the report;"],[3,"(ii) communication of that information among persons related by common ownership or affiliated by corporate control; or"],[3,"(iii) communication of other information among persons related by common ownership or affiliated by corporate control, if it is clearly and conspicuously disclosed to the consumer that the information may be communicated among such persons and the consumer is given the opportunity, before the time that the information is initially communicated, to direct that such information not be communicated among such persons;"],[2,"(B) any authorization or approval of a specific extension of credit directly or indirectly by the issuer of a credit card or similar device;"],[2,"(C) any report in which a person who has been requested by a third party to make a specific extension of credit directly or indirectly to a consumer conveys his or her decision with respect to such request, if the third party advises the consumer of the name and address of the person to whom the request was made, and such person makes the disclosures to the consumer required under section 1681m of this title; or"],[2,"(D) a communication described in subsection (o) or (x).1"],[1,"(3) Restriction on sharing of medical information.—Except for information or any communication of information disclosed as provided in section 1681b(g)(3) of this title, the exclusions in paragraph (2) shall not apply with respect to information disclosed to any person related by common ownership or affiliated by corporate control, if the information is—"],[2,"(A) medical information;"],[2,"(B) an individualized list or description based on the payment transactions of the consumer for medical products or services; or"],[2,"(C) an aggregate list of identified consumers based on payment transactions for medical products or services."],[0,"(e) The term \"investigative consumer report\" means a consumer report or portion thereof in which information on a consumer's character, general reputation, personal characteristics, or mode of living is obtained through personal interviews with neighbors, friends, or associates of the consumer reported on or with others with whom he is acquainted or who may have knowledge concerning any such items of information. However, such information shall not include specific factual information on a consumer's credit record obtained directly from a creditor of the consumer or from a consumer reporting agency when such information was obtained directly from a creditor of the consumer or from the consumer."],[0,"(f) The term \"consumer reporting agency\" means any person which, for monetary fees, dues, or on a cooperative nonprofit basis, regularly engages in whole or in part in the practice of assembling or evaluating consumer credit information or other information on consumers for the purpose of furnishing consumer reports to third parties, and which uses any means or facility of interstate commerce for the purpose of preparing or furnishing consumer reports."],[0,"(g) The term \"file\", when used in connection with information on any consumer, means all of the information on that consumer recorded and retained by a consumer reporting agency regardless of how the information is stored."],[0,"(h) The term \"employment purposes\" when used in connection with a consumer report means a report used for the purpose of evaluating a consumer for employment, promotion, reassignment or retention as an employee."],[0,"(i) Medical Information.—The term \"medical information\"—"],[1,"(1) means information or data, whether oral or recorded, in any form or medium, created by or derived from a health care provider or the consumer, that relates to—"],[2,"(A) the past, present, or future physical, mental, or behavioral health or condition of an individual;"],[2,"(B) the provision of health care to an individual; or"],[2,"(C) the payment for the provision of health care to an individual.2"],[1,"(2) does not include the age or gender of a consumer, demographic information about the consumer, including a consumer's residence address or e-mail address, or any other information about a consumer that does not relate to the physical, mental, or behavioral health or condition of a consumer, including the existence or value of any insurance policy."],[0,"(j) Definitions Relating to Child Support Obligations.—"],[1,"(1) Overdue support.—The term \"overdue support\" has the meaning given to such term in section 666(e) of title 42."],[1,"(2) State or local child support enforcement agency.—The term \"State or local child support enforcement agency\" means a State or local agency which administers a State or local program for establishing and enforcing child support obligations."],[0,"(k) Adverse Action.—"],[1,"(1) Actions included.—The term \"adverse action\"—"],[2,"(A) has the same meaning as in section 1691(d)(6) of this title; and"],[2,"(B) means—"],[3,"(i) a denial or cancellation of, an increase in any charge for, or a reduction or other adverse or unfavorable change in the terms of coverage or amount of, any insurance, existing or applied for, in connection with the underwriting of insurance;"],[3,"(ii) a denial of employment or any other decision for employment purposes that adversely affects any current or prospective employee;"],[3,"(iii) a denial or cancellation of, an increase in any charge for, or any other adverse or unfavorable change in the terms of, any license or benefit described in section 1681b(a)(3)(D) of this title; and"],[3,"(iv) an action taken or determination that is—"],[4,"(I) made in connection with an application that was made by, or a transaction that was initiated by, any consumer, or in connection with a review of an account under section 1681b(a)(3)(F)(ii) of this title; and"],[4,"(II) adverse to the interests of the consumer."],[1,"(2) Applicable findings, decisions, commentary, and orders.—For purposes of any determination of whether an action is an adverse action under paragraph (1)(A), all appropriate final findings, decisions, commentary, and orders issued under section 1691(d)(6) of this title by the Bureau or any court shall apply."],[0,"(l) Firm Offer of Credit or Insurance.—The term \"firm offer of credit or insurance\" means any offer of credit or insurance to a consumer that will be honored if the consumer is determined, based on information in a consumer report on the consumer, to meet the specific criteria used to select the consumer for the offer, except that the offer may be further conditioned on one or more of the following:"],[1,"(1) The consumer being determined, based on information in the consumer's application for the credit or insurance, to meet specific criteria bearing on credit worthiness or insurability, as applicable, that are established—"],[2,"(A) before selection of the consumer for the offer; and"],[2,"(B) for the purpose of determining whether to extend credit or insurance pursuant to the offer."],[1,"(2) Verification—"],[2,"(A) that the consumer continues to meet the specific criteria used to select the consumer for the offer, by using information in a consumer report on the consumer, information in the consumer's application for the credit or insurance, or other information bearing on the credit worthiness or insurability of the consumer; or"],[2,"(B) of the information in the consumer's application for the credit or insurance, to determine that the consumer meets the specific criteria bearing on credit worthiness or insurability."],[1,"(3) The consumer furnishing any collateral that is a requirement for the extension of the credit or insurance that was—"],[2,"(A) established before selection of the consumer for the offer of credit or insurance; and"],[2,"(B) disclosed to the consumer in the offer of credit or insurance."],[0,"(m) Credit or Insurance Transaction That Is Not Initiated by the Consumer.—The term \"credit or insurance transaction that is not initiated by the consumer\" does not include the use of a consumer report by a person with which the consumer has an account or insurance policy, for purposes of—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681a?type=usc&year=mostrecent&link-type=html"},"head":"§1681a. Definitions; rules of construction","tname":"Commerce and Trade","by":{"0":"17","1":"4, 8, 14, 40, 41, 52, 41, 52"}},{"t":"usc","label":"15 U.S.C. § 1681b","url":"https://www.law.cornell.edu/uscode/text/15/1681b","subs":["(b)(3)","(b)(2)","(b)(4)"],"stext":{"head":"§1681b. Permissible purposes of consumer reports","paras":[[0,"(a) In general"],[0,"Subject to subsection (c), any consumer reporting agency may furnish a consumer report under the following circumstances and no other:"],[1,"(1) In response to the order of a court having jurisdiction to issue such an order, a subpoena issued in connection with proceedings before a Federal grand jury, or a subpoena issued in accordance with section 5318 of title 31 or section 3486 of title 18."],[1,"(2) In accordance with the written instructions of the consumer to whom it relates."],[1,"(3) To a person which it has reason to believe—"],[2,"(A) intends to use the information in connection with a credit transaction involving the consumer on whom the information is to be furnished and involving the extension of credit to, or review or collection of an account of, the consumer; or"],[2,"(B) intends to use the information for employment purposes; or"],[2,"(C) intends to use the information in connection with the underwriting of insurance involving the consumer; or"],[2,"(D) intends to use the information in connection with a determination of the consumer's eligibility for a license or other benefit granted by a governmental instrumentality required by law to consider an applicant's financial responsibility or status; or"],[2,"(E) intends to use the information, as a potential investor or servicer, or current insurer, in connection with a valuation of, or an assessment of the credit or prepayment risks associated with, an existing credit obligation; or"],[2,"(F) otherwise has a legitimate business need for the information—"],[3,"(i) in connection with a business transaction that is initiated by the consumer; or"],[3,"(ii) to review an account to determine whether the consumer continues to meet the terms of the account."],[2,"(G) executive departments and agencies in connection with the issuance of government-sponsored individually-billed travel charge cards."],[1,"(4) In response to a request by the head of a State or local child support enforcement agency (or a State or local government official authorized by the head of such an agency), if the person making the request certifies to the consumer reporting agency that—"],[2,"(A) the consumer report is needed for the purpose of establishing an individual's capacity to make child support payments, determining the appropriate level of such payments, or enforcing a child support order, award, agreement, or judgment;"],[2,"(B) the parentage of the consumer for the child to which the obligation relates has been established or acknowledged by the consumer in accordance with State laws under which the obligation arises (if required by those laws); and"],[2,"(C) the consumer report will be kept confidential, will be used solely for a purpose described in subparagraph (A), and will not be used in connection with any other civil, administrative, or criminal proceeding, or for any other purpose."],[1,"(5) To an agency administering a State plan under section 654 of title 42 for use to set an initial or modified child support award."],[1,"(6) To the Federal Deposit Insurance Corporation or the National Credit Union Administration as part of its preparation for its appointment or as part of its exercise of powers, as conservator, receiver, or liquidating agent for an insured depository institution or insured credit union under the Federal Deposit Insurance Act [12 U.S.C. 1811 et seq.] or the Federal Credit Union Act [12 U.S.C. 1751 et seq.], or other applicable Federal or State law, or in connection with the resolution or liquidation of a failed or failing insured depository institution or insured credit union, as applicable."],[0,"(b) Conditions for furnishing and using consumer reports for employment purposes"],[0,"(1) Certification from user"],[1,"A consumer reporting agency may furnish a consumer report for employment purposes only if—"],[2,"(A) the person who obtains such report from the agency certifies to the agency that—"],[3,"(i) the person has complied with paragraph (2) with respect to the consumer report, and the person will comply with paragraph (3) with respect to the consumer report if paragraph (3) becomes applicable; and"],[3,"(ii) information from the consumer report will not be used in violation of any applicable Federal or State equal employment opportunity law or regulation; and"],[2,"(B) the consumer reporting agency provides with the report, or has previously provided, a summary of the consumer's rights under this subchapter, as prescribed by the Bureau under section 1681g(c)(3) 1 of this title."],[0,"(2) Disclosure to consumer"],[0,"(A) In general"],[2,"Except as provided in subparagraph (B), a person may not procure a consumer report, or cause a consumer report to be procured, for employment purposes with respect to any consumer, unless—"],[3,"(i) a clear and conspicuous disclosure has been made in writing to the consumer at any time before the report is procured or caused to be procured, in a document that consists solely of the disclosure, that a consumer report may be obtained for employment purposes; and"],[3,"(ii) the consumer has authorized in writing (which authorization may be made on the document referred to in clause (i)) the procurement of the report by that person."],[0,"(B) Application by mail, telephone, computer, or other similar means"],[2,"If a consumer described in subparagraph (C) applies for employment by mail, telephone, computer, or other similar means, at any time before a consumer report is procured or caused to be procured in connection with that application—"],[3,"(i) the person who procures the consumer report on the consumer for employment purposes shall provide to the consumer, by oral, written, or electronic means, notice that a consumer report may be obtained for employment purposes, and a summary of the consumer's rights under section 1681m(a)(3) 1 of this title; and"],[3,"(ii) the consumer shall have consented, orally, in writing, or electronically to the procurement of the report by that person."],[0,"(C) Scope"],[2,"Subparagraph (B) shall apply to a person procuring a consumer report on a consumer in connection with the consumer's application for employment only if—"],[3,"(i) the consumer is applying for a position over which the Secretary of Transportation has the power to establish qualifications and maximum hours of service pursuant to the provisions of section 31502 of title 49, or a position subject to safety regulation by a State transportation agency; and"],[3,"(ii) as of the time at which the person procures the report or causes the report to be procured the only interaction between the consumer and the person in connection with that employment application has been by mail, telephone, computer, or other similar means."],[0,"(3) Conditions on use for adverse actions"],[0,"(A) In general"],[2,"Except as provided in subparagraph (B), in using a consumer report for employment purposes, before taking any adverse action based in whole or in part on the report, the person intending to take such adverse action shall provide to the consumer to whom the report relates—"],[3,"(i) a copy of the report; and"],[3,"(ii) a description in writing of the rights of the consumer under this subchapter, as prescribed by the Bureau under section 1681g(c)(3) 1 of this title."],[0,"(B) Application by mail, telephone, computer, or other similar means"],[2,"(i) If a consumer described in subparagraph (C) applies for employment by mail, telephone, computer, or other similar means, and if a person who has procured a consumer report on the consumer for employment purposes takes adverse action on the employment application based in whole or in part on the report, then the person must provide to the consumer to whom the report relates, in lieu of the notices required under subparagraph (A) of this section and under section 1681m(a) of this title, within 3 business days of taking such action, an oral, written or electronic notification—"],[3,"(I) that adverse action has been taken based in whole or in part on a consumer report received from a consumer reporting agency;"],[3,"(II) of the name, address and telephone number of the consumer reporting agency that furnished the consumer report (including a toll-free telephone number established by the agency if the agency compiles and maintains files on consumers on a nationwide basis);"],[3,"(III) that the consumer reporting agency did not make the decision to take the adverse action and is unable to provide to the consumer the specific reasons why the adverse action was taken; and"],[3,"(IV) that the consumer may, upon providing proper identification, request a free copy of a report and may dispute with the consumer reporting agency the accuracy or completeness of any information in a report."],[2,"(ii) If, under clause (B)(i)(IV), the consumer requests a copy of a consumer report from the person who procured the report, then, within 3 business days of receiving the consumer's request, together with proper identification, the person must send or provide to the consumer a copy of a report and a copy of the consumer's rights as prescribed by the Bureau under section 1681g(c)(3) 1 of this title."],[0,"(C) Scope"],[2,"Subparagraph (B) shall apply to a person procuring a consumer report on a consumer in connection with the consumer's application for employment only if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681b?type=usc&year=mostrecent&link-type=html"},"head":"§1681b. Permissible purposes of consumer reports","tname":"Commerce and Trade","by":{"0":"16","1":"44, 53, 53, 52"}},{"t":"usc","label":"15 U.S.C. § 1681n","url":"https://www.law.cornell.edu/uscode/text/15/1681n","subs":["(a)(2)","(a)","(a)(1)(A)"],"stext":{"head":"§1681n. Civil liability for willful noncompliance","paras":[[0,"(a) In general"],[0,"Any person who willfully fails to comply with any requirement imposed under this subchapter with respect to any consumer is liable to that consumer in an amount equal to the sum of—"],[1,"(1)(A) any actual damages sustained by the consumer as a result of the failure or damages of not less than $100 and not more than $1,000; or"],[1,"(B) in the case of liability of a natural person for obtaining a consumer report under false pretenses or knowingly without a permissible purpose, actual damages sustained by the consumer as a result of the failure or $1,000, whichever is greater;"],[1,"(2) such amount of punitive damages as the court may allow; and"],[1,"(3) in the case of any successful action to enforce any liability under this section, the costs of the action together with reasonable attorney's fees as determined by the court."],[0,"(b) Civil liability for knowing noncompliance"],[0,"Any person who obtains a consumer report from a consumer reporting agency under false pretenses or knowingly without a permissible purpose shall be liable to the consumer reporting agency for actual damages sustained by the consumer reporting agency or $1,000, whichever is greater."],[0,"(c) Attorney's fees"],[0,"Upon a finding by the court that an unsuccessful pleading, motion, or other paper filed in connection with an action under this section was filed in bad faith or for purposes of harassment, the court shall award to the prevailing party attorney's fees reasonable in relation to the work expended in responding to the pleading, motion, or other paper."],[0,"(d) Clarification of willful noncompliance"],[0,"For the purposes of this section, any person who printed an expiration date on any receipt provided to a consumer cardholder at a point of sale or transaction between December 4, 2004, and June 3, 2008, but otherwise complied with the requirements of section 1681c(g) of this title for such receipt shall not be in willful noncompliance with section 1681c(g) of this title by reason of printing such expiration date on the receipt."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681n?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1681n. Civil liability for willful noncompliance","tname":"Commerce and Trade","by":{"0":"2, 12, 15","1":"passim, 4, 49, 13, 37"}},{"t":"usc","label":"15 U.S.C. § 1681o","url":"https://www.law.cornell.edu/uscode/text/15/1681o","stext":{"head":"§1681o. Civil liability for negligent noncompliance","paras":[[0,"(a) In general"],[0,"Any person who is negligent in failing to comply with any requirement imposed under this subchapter with respect to any consumer is liable to that consumer in an amount equal to the sum of—"],[1,"(1) any actual damages sustained by the consumer as a result of the failure; and"],[1,"(2) in the case of any successful action to enforce any liability under this section, the costs of the action together with reasonable attorney's fees as determined by the court."],[0,"(b) Attorney's fees"],[0,"On a finding by the court that an unsuccessful pleading, motion, or other paper filed in connection with an action under this section was filed in bad faith or for purposes of harassment, the court shall award to the prevailing party attorney's fees reasonable in relation to the work expended in responding to the pleading, motion, or other paper."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681o?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1681o. Civil liability for negligent noncompliance","tname":"Commerce and Trade","by":{"0":"2, 12","1":"passim"}},{"t":"usc","label":"15 U.S.C. § 1681p","url":"https://www.law.cornell.edu/uscode/text/15/1681p","subs":["(1)"],"stext":{"head":"§1681p. Jurisdiction of courts; limitation of actions","paras":[[0,"An action to enforce any liability created under this subchapter may be brought in any appropriate United States district court, without regard to the amount in controversy, or in any other court of competent jurisdiction, not later than the earlier of—"],[1,"(1) 2 years after the date of discovery by the plaintiff of the violation that is the basis for such liability; or"],[1,"(2) 5 years after the date on which the violation that is the basis for such liability occurs."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681p?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§1681p. Jurisdiction of courts; limitation of actions","tname":"Commerce and Trade","by":{"0":"13, 14, 15","1":"passim, 13, 38"}},{"t":"usc","label":"15 U.S.C. § 1681q","url":"https://www.law.cornell.edu/uscode/text/15/1681q","stext":{"head":"§1681q. Obtaining information under false pretenses","paras":[[0,"Any person who knowingly and willfully obtains information on a consumer from a consumer reporting agency under false pretenses shall be fined under title 18, imprisoned for not more than 2 years, or both."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681q?type=usc&year=mostrecent&link-type=html"},"head":"§1681q. Obtaining information under false pretenses","tname":"Commerce and Trade","by":{"0":"18","1":"14, 43"}},{"t":"usc","label":"15 U.S.C. § 1681s","url":"https://www.law.cornell.edu/uscode/text/15/1681s","subs":["(a)","(c)(1)"],"by":{"0":"18, 18","1":"14"}},{"t":"usc","label":"15 U.S.C. § 1681u","url":"https://www.law.cornell.edu/uscode/text/15/1681u","subs":["(i)"],"by":{"0":"20","1":"5, 14, 15, 48, 47"}},{"t":"usc","label":"28 U.S.C. § 1346","url":"https://www.law.cornell.edu/uscode/text/28/1346","subs":["(a)(2)","(b)(1)"],"stext":{"head":"§1346. United States as defendant","paras":[[0,"(a) The district courts shall have original jurisdiction, concurrent with the United States Court of Federal Claims, of:"],[1,"(1) Any civil action against the United States for the recovery of any internal-revenue tax alleged to have been erroneously or illegally assessed or collected, or any penalty claimed to have been collected without authority or any sum alleged to have been excessive or in any manner wrongfully collected under the internal-revenue laws;"],[1,"(2) Any other civil action or claim against the United States, not exceeding $10,000 in amount, founded either upon the Constitution, or any Act of Congress, or any regulation of an executive department, or upon any express or implied contract with the United States, or for liquidated or unliquidated damages in cases not sounding in tort, except that the district courts shall not have jurisdiction of any civil action or claim against the United States founded upon any express or implied contract with the United States or for liquidated or unliquidated damages in cases not sounding in tort which are subject to sections 7104(b)(1) and 7107(a)(1) of title 41. For the purpose of this paragraph, an express or implied contract with the Army and Air Force Exchange Service, Navy Exchanges, Marine Corps Exchanges, Coast Guard Exchanges, or Exchange Councils of the National Aeronautics and Space Administration shall be considered an express or implied contract with the United States."],[0,"(b)(1) Subject to the provisions of chapter 171 of this title, the district courts, together with the United States District Court for the District of the Canal Zone and the District Court of the Virgin Islands, shall have exclusive jurisdiction of civil actions on claims against the United States, for money damages, accruing on and after January 1, 1945, for injury or loss of property, or personal injury or death caused by the negligent or wrongful act or omission of any employee of the Government while acting within the scope of his office or employment, under circumstances where the United States, if a private person, would be liable to the claimant in accordance with the law of the place where the act or omission occurred."],[0,"(2) No person convicted of a felony who is incarcerated while awaiting sentencing or while serving a sentence may bring a civil action against the United States or an agency, officer, or employee of the Government, for mental or emotional injury suffered while in custody without a prior showing of physical injury or the commission of a sexual act (as defined in section 2246 of title 18)."],[0,"(c) The jurisdiction conferred by this section includes jurisdiction of any set-off, counterclaim, or other claim or demand whatever on the part of the United States against any plaintiff commencing an action under this section."],[0,"(d) The district courts shall not have jurisdiction under this section of any civil action or claim for a pension."],[0,"(e) The district courts shall have original jurisdiction of any civil action against the United States provided in section 6226, 6228(a), 7426, or 7428 (in the case of the United States district court for the District of Columbia) or section 7429 of the Internal Revenue Code of 1986."],[0,"(f) The district courts shall have exclusive original jurisdiction of civil actions under section 2409a to quiet title to an estate or interest in real property in which an interest is claimed by the United States."],[0,"(g) Subject to the provisions of chapter 179, the district courts of the United States shall have exclusive jurisdiction over any civil action commenced under section 453(2) of title 3, by a covered employee under chapter 5 of such title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1346?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§1346. United States as defendant","tname":"Judiciary and Judicial Procedure","by":{"0":"2, 13, 11","1":"4, 33, passim"}},{"t":"usc","label":"29 U.S.C. § 794","url":"https://www.law.cornell.edu/uscode/text/29/794","subs":["(a)"],"stext":{"head":"§794. Nondiscrimination under Federal grants and programs","paras":[[0,"(a) Promulgation of rules and regulations"],[0,"No otherwise qualified individual with a disability in the United States, as defined in section 705(20) of this title, shall, solely by reason of her or his disability, be excluded from the participation in, be denied the benefits of, or be subjected to discrimination under any program or activity receiving Federal financial assistance or under any program or activity conducted by any Executive agency or by the United States Postal Service. The head of each such agency shall promulgate such regulations as may be necessary to carry out the amendments to this section made by the Rehabilitation, Comprehensive Services, and Developmental Disabilities Act of 1978. Copies of any proposed regulation shall be submitted to appropriate authorizing committees of the Congress, and such regulation may take effect no earlier than the thirtieth day after the date on which such regulation is so submitted to such committees."],[0,"(b) \"Program or activity\" defined"],[0,"For the purposes of this section, the term \"program or activity\" means all of the operations of—"],[1,"(1)(A) a department, agency, special purpose district, or other instrumentality of a State or of a local government; or"],[1,"(B) the entity of such State or local government that distributes such assistance and each such department or agency (and each other State or local government entity) to which the assistance is extended, in the case of assistance to a State or local government;"],[1,"(2)(A) a college, university, or other postsecondary institution, or a public system of higher education; or"],[1,"(B) a local educational agency (as defined in section 7801 of title 20), system of career and technical education, or other school system;"],[1,"(3)(A) an entire corporation, partnership, or other private organization, or an entire sole proprietorship—"],[2,"(i) if assistance is extended to such corporation, partnership, private organization, or sole proprietorship as a whole; or"],[2,"(ii) which is principally engaged in the business of providing education, health care, housing, social services, or parks and recreation; or"],[1,"(B) the entire plant or other comparable, geographically separate facility to which Federal financial assistance is extended, in the case of any other corporation, partnership, private organization, or sole proprietorship; or"],[1,"(4) any other entity which is established by two or more of the entities described in paragraph (1), (2), or (3);"],[0,"any part of which is extended Federal financial assistance."],[0,"(c) Significant structural alterations by small providers"],[0,"Small providers are not required by subsection (a) to make significant structural alterations to their existing facilities for the purpose of assuring program accessibility, if alternative means of providing the services are available. The terms used in this subsection shall be construed with reference to the regulations existing on March 22, 1988."],[0,"(d) Standards used in determining violation of section"],[0,"The standards used to determine whether this section has been violated in a complaint alleging employment discrimination under this section shall be the standards applied under title I of the Americans with Disabilities Act of 1990 (42 U.S.C. 12111 et seq.) and the provisions of sections 501 through 504, and 510,1 of the Americans with Disabilities Act of 1990 (42 U.S.C. 12201–12204 and 12210), as such sections relate to employment."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/794?type=usc&year=mostrecent&link-type=html"},"head":"§794. Nondiscrimination under Federal grants and programs","tname":"Labor","by":{"0":"4","1":"28"}},{"t":"usc","label":"28 U.S.C. § 1491","url":"https://www.law.cornell.edu/uscode/text/28/1491","subs":["(a)(1)"],"stext":{"head":"§1491. Claims against United States generally; actions involving Tennessee Valley Authority","paras":[[0,"(a)(1) The United States Court of Federal Claims shall have jurisdiction to render judgment upon any claim against the United States founded either upon the Constitution, or any Act of Congress or any regulation of an executive department, or upon any express or implied contract with the United States, or for liquidated or unliquidated damages in cases not sounding in tort. For the purpose of this paragraph, an express or implied contract with the Army and Air Force Exchange Service, Navy Exchanges, Marine Corps Exchanges, Coast Guard Exchanges, or Exchange Councils of the National Aeronautics and Space Administration shall be considered an express or implied contract with the United States."],[0,"(2) To provide an entire remedy and to complete the relief afforded by the judgment, the court may, as an incident of and collateral to any such judgment, issue orders directing restoration to office or position, placement in appropriate duty or retirement status, and correction of applicable records, and such orders may be issued to any appropriate official of the United States. In any case within its jurisdiction, the court shall have the power to remand appropriate matters to any administrative or executive body or official with such direction as it may deem proper and just. The Court of Federal Claims shall have jurisdiction to render judgment upon any claim by or against, or dispute with, a contractor arising under section 7104(b)(1) of title 41, including a dispute concerning termination of a contract, rights in tangible or intangible property, compliance with cost accounting standards, and other nonmonetary disputes on which a decision of the contracting officer has been issued under section 6 1 of that Act."],[0,"(b)(1) Both the Unites 2 States Court of Federal Claims and the district courts of the United States shall have jurisdiction to render judgment on an action by an interested party objecting to a solicitation by a Federal agency for bids or proposals for a proposed contract or to a proposed award or the award of a contract or any alleged violation of statute or regulation in connection with a procurement or a proposed procurement. Both the United States Court of Federal Claims and the district courts of the United States shall have jurisdiction to entertain such an action without regard to whether suit is instituted before or after the contract is awarded."],[0,"(2) To afford relief in such an action, the courts may award any relief that the court considers proper, including declaratory and injunctive relief except that any monetary relief shall be limited to bid preparation and proposal costs."],[0,"(3) In exercising jurisdiction under this subsection, the courts shall give due regard to the interests of national defense and national security and the need for expeditious resolution of the action."],[0,"(4) In any action under this subsection, the courts shall review the agency's decision pursuant to the standards set forth in section 706 of title 5."],[0,"(5) If an interested party who is a member of the private sector commences an action described in paragraph (1) with respect to a public-private competition conducted under Office of Management and Budget Circular A–76 regarding the performance of an activity or function of a Federal agency, or a decision to convert a function performed by Federal employees to private sector performance without a competition under Office of Management and Budget Circular A–76, then an interested party described in section 3551(2)(B) of title 31 shall be entitled to intervene in that action."],[0,"(6) Jurisdiction over any action described in paragraph (1) arising out of a maritime contract, or a solicitation for a proposed maritime contract, shall be governed by this section and shall not be subject to the jurisdiction of the district courts of the United States under the Suits in Admiralty Act (chapter 309 of title 46) or the Public Vessels Act (chapter 311 of title 46)."],[0,"(c) Nothing herein shall be construed to give the United States Court of Federal Claims jurisdiction of any civil action within the exclusive jurisdiction of the Court of International Trade, or of any action against, or founded on conduct of, the Tennessee Valley Authority, or to amend or modify the provisions of the Tennessee Valley Authority Act of 1933 with respect to actions by or against the Authority."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1491?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1491. Claims against United States generally; actions involving Tennessee Valley Authority","tname":"Judiciary and Judicial Procedure","by":{"0":"2, 13","1":"passim"}},{"t":"usc","label":"28 U.S.C. § 2401","url":"https://www.law.cornell.edu/uscode/text/28/2401","subs":["(a)"],"stext":{"head":"§2401. Time for commencing action against United States","paras":[[0,"(a) Except as provided by chapter 71 of title 41, every civil action commenced against the United States shall be barred unless the complaint is filed within six years after the right of action first accrues. The action of any person under legal disability or beyond the seas at the time the claim accrues may be commenced within three years after the disability ceases."],[0,"(b) A tort claim against the United States shall be forever barred unless it is presented in writing to the appropriate Federal agency within two years after such claim accrues or unless action is begun within six months after the date of mailing, by certified or registered mail, of notice of final denial of the claim by the agency to which it was presented."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2401?type=usc&year=mostrecent&link-type=html"},"head":"§2401. Time for commencing action against United States","tname":"Judiciary and Judicial Procedure","by":{"0":"15","1":"13, 38"}},{"t":"usc","label":"28 U.S.C. § 2501","url":"https://www.law.cornell.edu/uscode/text/28/2501","stext":{"head":"§2501. Time for filing suit","paras":[[0,"Every claim of which the United States Court of Federal Claims has jurisdiction shall be barred unless the petition thereon is filed within six years after such claim first accrues."],[0,"Every claim under section 1497 of this title shall be barred unless the petition thereon is filed within two years after the termination of the river and harbor improvements operations on which the claim is based."],[0,"A petition on the claim of a person under legal disability or beyond the seas at the time the claim accrues may be filed within three years after the disability ceases."],[0,"A suit for the fees of an officer of the United States shall not be filed until his account for such fees has been finally acted upon, unless the Government Accountability Office fails to act within six months after receiving the account."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2501?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2501. Time for filing suit","tname":"Judiciary and Judicial Procedure","by":{"0":"15","1":"13, 38"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","by":{"0":"12"}},{"t":"case","label":"Bank One Chi. N.A. v. Midwest Bank & Trust Co.","cite":"516 U.S. 264","y":1996,"id":"1995/94-1175","sc":1,"sum":"The Court held that the act provides for federal-court jurisdiction not only in suits between customers and banks, but also in cases initiated by one bank against another bank. Justice Ginsburg wrote for the Court that section 4010 of the act authorizes claims for relief that are enforceable in federal court.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Bigby v. United States","cite":"188 U.S. 400","y":1903,"id":"scdb/1902-060","sc":1,"sum":"There is no contract, express or implied, which can be made the basis for jurisdiction by a United States Circuit Court under the act of Congress of March 3, 1887, known as the Tucker Act, between the United States and a person who, while properly in a government building, sustains injuries by the fall of an elevator belonging to the government and operated by one of its employes. An action against the United States …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"30, 31"}},{"t":"case","label":"Bowen v. Massachusetts","cite":"487 U.S. 879","y":1988,"id":"1987/87-712","sc":1,"op":1,"ar":1,"sum":"The federal contribution (referred to as a \"reimbursement\") to a State's Medicaid program takes the form of advances based on the State's estimate of its future expenditures for covered services. Overpayments may be withheld from future advances, or, if a disallowance dispute develops, may be retained by the State at its option pending resolution of the dispute. After Massachusetts was reimbursed by the Department …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"27"}},{"t":"case","label":"Brown v. United States","cite":"105 F.3d 621","y":1997,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/105/621/","by":{"1":"50"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"Crozier v. Fried. Krupp Aktiengesell-schaft","cite":"224 U.S. 290","y":1912,"id":"scdb/1911-210","sc":1,"sum":"Prior to the passage of the act of June 25, 1910, 36 Stat. 851, c. 423, a patentee, whose patent was infringed by an officer of the United States, could not sue the United States unless a contract to pay was implied; and the object of the statute is to afford a remedy under circumstances where no contract can be implied, but where the property rights of the inventor have been appropriated by an officer of the United …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"33"}},{"t":"case","label":"Doe v. Chao","cite":"540 U.S. 614","y":2004,"id":"2003/02-1377","sc":1,"sum":"The Court reasoned that \"a straightforward textual analysis\" of the Privacy Act shows that the statute guarantees the $1000 minimum for victims of willful Privacy Act violations only in relation to \"actual damages sustained.\" Individuals subjected to an adverse effect - like the miners in this case - have \"injury enough to open the courthouse door, but without more\" have \"no cause of action for damages under the Privacy Act.\".","sumSrc":"Oyez","by":{"1":"49, 50"}},{"t":"case","label":"EC Term of Years Trust v. United States","cite":"550 U.S. 429","y":2007,"id":"2006/05-1541","sc":1,"op":2,"sum":"The Court ruled that \"Resisting the force of the better-fitted statute [28 U.S.C. 7426] requires a good countervailing reason, and none appears here.\" The Court held that Section 7426 is the exclusive legal vehicle for challenging a wrongful tax levy, so after having missed the deadline EC Term of Years Trust could not bring its suit as a tax refund claim under 1346(a)(1).","sumSrc":"Oyez","by":{"1":"23, 38"}},{"t":"case","label":"FDIC v. Meyer","cite":"510 U.S. 471","y":1994,"id":"1993/92-741","sc":1,"sum":"After the Federal Savings and Loan Insurance Corporation (FSLIC), as receiver for a failing thrift institution, terminated respondent Meyer from his job as a senior officer of that institution, he filed this suit in the District Court, claiming that his summary discharge deprived him of a property right without due process of law in violation of the Fifth Amendment. In making this claim, he relied on Bivens v. Six …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"33"}},{"t":"case","label":"Fitzpatrick v. IRS","cite":"665 F.2d 327","y":1982,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/665/327/","by":{"1":"50"}},{"t":"case","label":"Glidden Co. v. Zdanok","cite":"370 U.S. 530","y":1962,"id":"1961/242","sc":1,"op":1,"sum":"The Court held that judges in the United States Court of Claims and the United States Court of Customs and Patent Appeals constitutionally protected in tenure and compensation under Article III of the Constitution.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Goodyear Atomic Corp. v. Miller","cite":"486 U.S. 174","y":1988,"id":"1987/86-1172","sc":1,"sum":"Appellee Miller, an employee of appellant at an Ohio nuclear production facility owned by the United States but operated by appellant, a private contractor, received a workers' compensation award from appellee Ohio Industrial Commission (Commission) for injuries sustained in a fall allegedly caused by a bolt protruding from the scaffold on which he was working. On the basis of a state safety regulation prohibiting …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"55"}},{"t":"case","label":"Hercules, Inc. v. United States","cite":"516 U.S. 417","y":1996,"id":"1995/94-818","sc":1,"sum":"The Court held that the manufacturers may not recover on their warranty-of-specifications and contractual-indemnification claims.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"International Primate Prot. League v. Administrators of Tulane Educ. Fund","cite":"500 U.S. 72","y":1991,"id":"1990/90-89","sc":1,"sum":"Petitioners, organizations and individuals seeking the humane treatment of animals, filed suit in a Louisiana court to enjoin respondents, the Institutes for Behavior Resources (IBR), the National Institutes of Health (NIH), and the Administrators of the Tulane Educational Fund (Tulane), from using certain monkeys for federally funded medical experiments and to obtain custody over the animals. NIH removed the case …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"46"}},{"t":"case","label":"Library of Congress v. Shaw","cite":"478 U.S. 310","y":1986,"id":"1985/85-54","sc":1,"sum":"The no-interest rule applies here so as to preclude the award of increased compensation to respondent's counsel for the delay in receiving payment for his services.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"46"}},{"t":"case","label":"Lindahl v. OPM","cite":"470 U.S. 768","y":1985,"id":"1984/83-5954","sc":1,"sum":"The Office of Personnel Management (OPM) \"determine[s] questions of disability and dependency\" in administering the Federal Government's disability retirement program. 5 U. S. C. § 8347(c). Its \"decisions... concerning these matters are final and conclusive and are not subject to review,\" ibid., except to the extent that administrative review by the Merit Systems Protection Board (MSPB) is provided by §8347(d)(1). …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20"}},{"t":"case","label":"Presidential Gardens Assocs. v. United States","cite":"175 F.3d 132","y":1999,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/175/132/","by":{"1":"37"}},{"t":"case","label":"Robinson v. Shell Oil Co.","cite":"519 U.S. 337","y":1997,"id":"1996/95-1376","sc":1,"sum":"Authored by Justice Clarence Thomas, the Court ruled that because the term \"employees,\" as used Title VII of the Civil Rights Act of 1964, includes former employees, Robinson may sue Shell for its allegedly retaliatory post-employment actions.","sumSrc":"Oyez","by":{"1":"41"}},{"t":"case","label":"TRW Inc. v. Andrews","cite":"534 U.S. 19","y":2001,"id":"2001/00-1045","sc":1,"sum":"The Court held that a discovery rule does not govern section 1681p of FCRA, as that section explicitly delineated the exceptional case in which discovery triggered the two-year limitation and Adelaide's case does not fall within the exceptional category. The Court reasoned that it was not at liberty to make Congress' explicit exception the general rule.","sumSrc":"Oyez","by":{"1":"3"}},{"t":"case","label":"Talley v. United States Dep’t of Agric.","cite":"595 F.3d 754","y":2010,"url":"https://www.courtlistener.com/c/F.3d/595/754/","by":{"1":"36, 37"}},{"t":"case","label":"U.S. Postal Serv. v. Flamingo Indus. (USA) Ltd.","cite":"540 U.S. 736","y":2004,"id":"2003/02-1290","sc":1,"sum":"The Court held that the U.S. Postal Service cannot be sued under antitrust laws. The Court acknowledged the Postal Reorganization Act may waive the Postal Service's immunity from suit. However, federal antitrust laws (the Sherman Act, for example) do not allow the federal government - of which the Postal Service is a part - to be sued.","sumSrc":"Oyez","by":{"1":"46"}},{"t":"case","label":"United States v. Berdan Firearms Mfg. Co.","cite":"156 U.S. 552","y":1895,"id":"scdb/1894-118","sc":1,"sum":"Even if there were findings sufficient to show that the United States had in any manner infringed letters patent No. 52,925, granted February 27,1866-, to Hiram Berdan for an improvement in breech-loading fire-arms, in the absence of anything disclosing a contract the use would be a tort, creating no cause of action cognizable in the Court of Claims.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"32"}},{"t":"case","label":"United States v. Hohri","cite":"482 U.S. 64","y":1987,"id":"1986/86-510","sc":1,"sum":"The Federal Circuit rather than the appropriate regional court of appeals has jurisdiction over an appeal from a district court's decision of a \"mixed\" case raising both a nontax Little Tucker Act claim and an FTCA claim.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"case","label":"United States v. Nordic Village, Inc.","cite":"503 U.S. 30","y":1992,"id":"1991/90-1629","sc":1,"op":1,"sum":"After respondent Nordic Village, Inc., filed a petition for relief under Chapter 11 of the Bankruptcy Code, one of its officers withdrew funds from the company's corporate account. He sent part of the money to the Internal Revenue Service (IRS), directing it to apply the funds against his individual tax liability, which it did. In a subsequent adversary proceeding, the Bankruptcy Court permitted Nordic Village's …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"4, 55"}},{"t":"case","label":"United States v. Park Place Assocs., Ltd .","cite":"563 F.3d 907","y":2009,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/563/907/","by":{"1":"37"}},{"t":"case","label":"United States v. United Mine Workers of Am.","cite":"330 U.S. 258","y":1947,"id":"scdb/1946-060","sc":1,"sum":"1. Neither the Norris-LaGuardia Act, 47 Stat. 70, nor § 20 of the Clayton Act, 38 Stat. 738, deprives a federal district court of jurisdiction to issue a restraining order and preliminary injunction in a suit by the Government to prevent a union and its officers from precipitating a nation-wide strike in the bituminous coal mines pending judicial interpretation of a labor contract between the Government and the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"46"}},{"t":"law","label":"Pub. L. No. 91-508","url":"https://www.govinfo.gov/link/statute/84/1128","by":{"1":"41"}},{"t":"law","label":"Pub. L. No. 97-452","url":"https://www.govinfo.gov/link/statute/96/2470","by":{"1":"54"}},{"t":"law","label":"Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"1":"43"}},{"t":"law","label":"Pub. L. No. 104-134","url":"https://www.govinfo.gov/link/plaw/104/public/134","by":{"1":"54"}},{"t":"usc","label":"15 U.S.C. § 1681c","url":"https://www.law.cornell.edu/uscode/text/15/1681c","subs":["(a)","(g)(1)"],"by":{"1":"31, 3, 32, 51"}},{"t":"usc","label":"15 U.S.C. § 1681k","url":"https://www.law.cornell.edu/uscode/text/15/1681k","subs":["(b)"],"by":{"1":"53"}},{"t":"usc","label":"15 U.S.C. § 1681m","url":"https://www.law.cornell.edu/uscode/text/15/1681m","subs":["(a)","(h)(8)(A)"],"by":{"1":"44, 23"}},{"t":"usc","label":"15 U.S.C. § 1681s-2","url":"https://www.law.cornell.edu/uscode/text/15/1681s-2","subs":["(b)","(c)"],"by":{"1":"52, 49, 52, 23"}},{"t":"law","label":"Pub. L. No. 108-159","url":"https://www.govinfo.gov/link/plaw/108/public/159","by":{"1":"51"}},{"t":"usc","label":"28 U.S.C. § 1505","url":"https://www.law.cornell.edu/uscode/text/28/1505","stext":{"head":"§1505. Indian claims","paras":[[0,"The United States Court of Federal Claims shall have jurisdiction of any claim against the United States accruing after August 13, 1946, in favor of any tribe, band, or other identifiable group of American Indians residing within the territorial limits of the United States or Alaska whenever such claim is one arising under the Constitution, laws or treaties of the United States, or Executive orders of the President, or is one which otherwise would be cognizable in the Court of Federal Claims if the claimant were not an Indian tribe, band or group."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1505?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1505. Indian claims","tname":"Judiciary and Judicial Procedure","by":{"1":"20, 26, 27"}},{"t":"usc","label":"42 U.S.C. § 1396b","url":"https://www.law.cornell.edu/uscode/text/42/1396b","subs":["(a)"],"by":{"1":"27"}},{"t":"usc","label":"5 U.S.C. § 552a","url":"https://www.law.cornell.edu/uscode/text/5/552a","subs":["(a)(1)","(b)","(c)(4)","(d)","(g)","(g)(1)(B)","(g)(4)"],"by":{"1":"48, 15, 48, 48, 48, 49, 49, 15, 48, 49, 49"}},{"t":"usc","label":"28 U.S.C. § 2409a","url":"https://www.law.cornell.edu/uscode/text/28/2409a","subs":["(a)"],"by":{"1":"4"}},{"t":"usc","label":"1 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/1/1","stext":{"head":"§1. Words denoting number, gender, and so forth","paras":[[0,"In determining the meaning of any Act of Congress, unless the context indicates otherwise—"],[1,"words importing the singular include and apply to several persons, parties, or things;"],[1,"words importing the plural include the singular;"],[1,"words importing the masculine gender include the feminine as well;"],[1,"words used in the present tense include the future as well as the present;"],[1,"the words \"insane\" and \"insane person\" shall include every idiot, insane person, and person non compos mentis;"],[1,"the words \"person\" and \"whoever\" include corporations, companies, associations, firms, partnerships, societies, and joint stock companies, as well as individuals;"],[1,"\"officer\" includes any person authorized by law to perform the duties of the office;"],[1,"\"signature\" or \"subscription\" includes a mark when the person making the same intended it as such;"],[1,"\"oath\" includes affirmation, and \"sworn\" includes affirmed;"],[1,"\"writing\" includes printing and typewriting and reproductions of visual symbols by photographing, multigraphing, mimeographing, manifolding, or otherwise."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/1/1?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§1. Words denoting number, gender, and so forth","tname":"General Provisions","by":{"1":"46"}},{"t":"usc","label":"25 U.S.C. § 635","url":"https://www.law.cornell.edu/uscode/text/25/635","subs":["(a)"],"by":{"1":"27"}},{"t":"usc","label":"25 U.S.C. § 638","url":"https://www.law.cornell.edu/uscode/text/25/638","by":{"1":"27"}},{"t":"usc","label":"28 U.S.C. § 1291","url":"https://www.law.cornell.edu/uscode/text/28/1291","by":{"1":"6, 55"}},{"t":"usc","label":"28 U.S.C. § 1295","url":"https://www.law.cornell.edu/uscode/text/28/1295","subs":["(a)(2)"],"stext":{"head":"§1295. Jurisdiction of the United States Court of Appeals for the Federal Circuit","paras":[[0,"(a) The United States Court of Appeals for the Federal Circuit shall have exclusive jurisdiction—"],[1,"(1) of an appeal from a final decision of a district court of the United States, the District Court of Guam, the District Court of the Virgin Islands, or the District Court of the Northern Mariana Islands, in any civil action arising under, or in any civil action in which a party has asserted a compulsory counterclaim arising under, any Act of Congress relating to patents or plant variety protection;"],[1,"(2) of an appeal from a final decision of a district court of the United States, the United States District Court for the District of the Canal Zone, the District Court of Guam, the District Court of the Virgin Islands, or the District Court for the Northern Mariana Islands, if the jurisdiction of that court was based, in whole or in part, on section 1346 of this title, except that jurisdiction of an appeal in a case brought in a district court under section 1346(a)(1), 1346(b), 1346(e), or 1346(f) of this title or under section 1346(a)(2) when the claim is founded upon an Act of Congress or a regulation of an executive department providing for internal revenue shall be governed by sections 1291, 1292, and 1294 of this title;"],[1,"(3) of an appeal from a final decision of the United States Court of Federal Claims;"],[1,"(4) of an appeal from a decision of—"],[2,"(A) the Patent Trial and Appeal Board of the United States Patent and Trademark Office with respect to a patent application, derivation proceeding, reexamination, post-grant review, or inter partes review under title 35, at the instance of a party who exercised that party's right to participate in the applicable proceeding before or appeal to the Board, except that an applicant or a party to a derivation proceeding may also have remedy by civil action pursuant to section 145 or 146 of title 35; an appeal under this subparagraph of a decision of the Board with respect to an application or derivation proceeding shall waive the right of such applicant or party to proceed under section 145 or 146 of title 35;"],[2,"(B) the Under Secretary of Commerce for Intellectual Property and Director of the United States Patent and Trademark Office or the Trademark Trial and Appeal Board with respect to applications for registration of marks and other proceedings as provided in section 21 of the Trademark Act of 1946 (15 U.S.C. 1071); or"],[2,"(C) a district court to which a case was directed pursuant to section 145, 146, or 154(b) of title 35;"],[1,"(5) of an appeal from a final decision of the United States Court of International Trade;"],[1,"(6) to review the final determinations of the United States International Trade Commission relating to unfair practices in import trade, made under section 337 of the Tariff Act of 1930 (19 U.S.C. 1337);"],[1,"(7) to review, by appeal on questions of law only, findings of the Secretary of Commerce under U.S. note 6 to subchapter X of chapter 98 of the Harmonized Tariff Schedule of the United States (relating to importation of instruments or apparatus);"],[1,"(8) of an appeal under section 71 of the Plant Variety Protection Act (7 U.S.C. 2461);"],[1,"(9) of an appeal from a final order or final decision of the Merit Systems Protection Board, pursuant to sections 7703(b)(1) and 7703(d) of title 5;"],[1,"(10) of an appeal from a final decision of an agency board of contract appeals pursuant to section 7107(a)(1) of title 41;"],[1,"(11) of an appeal under section 211 of the Economic Stabilization Act of 1970;"],[1,"(12) of an appeal under section 5 of the Emergency Petroleum Allocation Act of 1973;"],[1,"(13) of an appeal under section 506(c) of the Natural Gas Policy Act of 1978; and"],[1,"(14) of an appeal under section 523 of the Energy Policy and Conservation Act."],[0,"(b) The head of any executive department or agency may, with the approval of the Attorney General, refer to the Court of Appeals for the Federal Circuit for judicial review any final decision rendered by a board of contract appeals pursuant to the terms of any contract with the United States awarded by that department or agency which the head of such department or agency has concluded is not entitled to finality pursuant to the review standards specified in section 7107(b) of title 41. The head of each executive department or agency shall make any referral under this section within one hundred and twenty days after the receipt of a copy of the final appeal decision."],[0,"(c) The Court of Appeals for the Federal Circuit shall review the matter referred in accordance with the standards specified in section 7107(b) of title 41. The court shall proceed with judicial review on the administrative record made before the board of contract appeals on matters so referred as in other cases pending in such court, shall determine the issue of finality of the appeal decision, and shall, if appropriate, render judgment thereon, or remand the matter to any administrative or executive body or official with such direction as it may deem proper and just."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1295?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1295. Jurisdiction of the United States Court of Appeals for the Federal Circuit","tname":"Judiciary and Judicial Procedure","by":{"1":"5, 6, 55, 20"}},{"t":"usc","label":"30 U.S.C. § 1300","url":"https://www.law.cornell.edu/uscode/text/30/1300","subs":["(e)"],"by":{"1":"27"}},{"t":"usc","label":"31 U.S.C. § 3711","url":"https://www.law.cornell.edu/uscode/text/31/3711","subs":["(e)"],"by":{"1":"48"}}]};